"""
ImageTagger Setup & Launcher
Build as a Windows GUI executable with:
    pyinstaller --onefile --windowed --name ImageTaggerSetup imagetagger_setup.py

The installer downloads a private portable Python runtime, installs only the
dependencies required by ImageTagger, downloads the DeepDanbooru model, then
launches ImageTagger. No launcher menu or unrelated applications.
"""
import base64
import os
import queue
import shutil
import subprocess
import sys
import threading
import urllib.request
import zipfile
from pathlib import Path
import tkinter as tk
from tkinter import ttk, messagebox

APP_NAME = "ImageTagger"
PYTHON_VERSION = "3.10.5"
PYTHON_URL = (
    "https://www.python.org/ftp/python/3.10.5/"
    "python-3.10.5-embed-amd64.zip"
)
GET_PIP_URL = "https://bootstrap.pypa.io/get-pip.py"
MODEL_URL = (
    "https://github.com/KichangKim/DeepDanbooru/releases/download/"
    "v3-20211112-sgd-e28/deepdanbooru-v3-20211112-sgd-e28.zip"
)
MODEL_FOLDER = "deepdanbooru-v3-20211112-sgd-e28"
MODEL_ZIP_NAME = "deepdanbooru-model.zip"
APP_FILE_NAME = "autotagger.py"

# This is the ImageTagger application source, embedded so this setup script
# remains a single-file project and can be packaged as one EXE.
APP_SOURCE_B64 = ""

ROOT = Path(sys.executable).resolve().parent if getattr(sys, "frozen", False) else Path(__file__).resolve().parent
RUNTIME_DIR = ROOT / "python"
PYTHON_EXE = RUNTIME_DIR / "python.exe"
MODEL_DIR = ROOT / "models" / MODEL_FOLDER
APP_FILE = ROOT / APP_FILE_NAME
EVENTS = queue.Queue()
STEPS = [
    "Prepare portable Python",
    "Install pip",
    "Install ImageTagger libraries",
    "Download DeepDanbooru model",
    "Extract model files",
    "Start ImageTagger",
]

def emit(kind, *values):
    EVENTS.put((kind, *values))

def download(url, destination, label):
    destination = Path(destination)
    destination.parent.mkdir(parents=True, exist_ok=True)
    request = urllib.request.Request(url, headers={"User-Agent": "ImageTagger-Setup/1.0"})
    with urllib.request.urlopen(request, timeout=60) as response:
        total = int(response.headers.get("Content-Length", "0") or 0)
        downloaded = 0
        with open(destination, "wb") as out:
            while True:
                chunk = response.read(1024 * 1024)
                if not chunk:
                    break
                out.write(chunk)
                downloaded += len(chunk)
                if total:
                    emit("progress", downloaded / total, f"{label}: {downloaded / 1048576:.1f} / {total / 1048576:.1f} MB")
                else:
                    emit("status", f"{label}: {downloaded / 1048576:.1f} MB downloaded")
    emit("progress", 1.0, f"{label}: complete")

def run_command(args, description):
    emit("status", description)
    process = subprocess.Popen(
        args, cwd=str(ROOT), stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT, text=True, errors="replace",
        bufsize=1
    )
    output = []
    for line in process.stdout:
        line = line.rstrip()
        if line:
            output.append(line)
            emit("status", line[-180:])
    code = process.wait()
    if code:
        tail = "\\n".join(output[-45:])
        raise RuntimeError(f"{description} failed.\\n\\n{tail}")

def install():
    try:
        # 1. Portable Python
        emit("step", 0)
        ROOT.mkdir(parents=True, exist_ok=True)
        if not PYTHON_EXE.exists():
            py_zip = ROOT / "python-embed.zip"
            download(PYTHON_URL, py_zip, "Portable Python")
            emit("status", "Extracting portable Python…")
            RUNTIME_DIR.mkdir(parents=True, exist_ok=True)
            with zipfile.ZipFile(py_zip) as zf:
                zf.extractall(RUNTIME_DIR)
            py_zip.unlink(missing_ok=True)
        if not PYTHON_EXE.exists():
            raise RuntimeError("Portable Python extraction did not produce python.exe.")

        # Enable site-packages for the embeddable Python distribution.
        pth = RUNTIME_DIR / "python310._pth"
        if pth.exists():
            lines = pth.read_text(encoding="utf-8").splitlines()
            for entry in ("Lib\\site-packages", "import site"):
                if entry not in lines:
                    lines.append(entry)
            pth.write_text("\n".join(lines) + "\n", encoding="utf-8")

        # 2. pip
        emit("step", 1)
        pip_check = subprocess.run(
            [str(PYTHON_EXE), "-m", "pip", "--version"],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL
        )
        if pip_check.returncode:
            get_pip = ROOT / "get-pip.py"
            download(GET_PIP_URL, get_pip, "pip installer")
            run_command([str(PYTHON_EXE), str(get_pip), "--disable-pip-version-check"], "Installing pip")
            get_pip.unlink(missing_ok=True)

        # 3. Only libraries used by ImageTagger
        emit("step", 2)
        run_command([
            str(PYTHON_EXE), "-m", "pip", "install",
            "--disable-pip-version-check",
            "numpy==1.23.5",
            "Pillow==10.4.0",
            "PyQt5==5.15.10",
            "tensorflow==2.10.1",
            "protobuf==3.19.6",
        ], "Installing TensorFlow, PyQt5, Pillow and NumPy")

        # Write the sole application into the same folder as this launcher.
        APP_FILE.write_bytes(base64.b64decode(APP_SOURCE_B64))

        # 4. Model download (skip if already installed)
        emit("step", 3)
        model_file = MODEL_DIR / "project.json"
        if not model_file.exists():
            archive = ROOT / MODEL_ZIP_NAME
            download(MODEL_URL, archive, "DeepDanbooru model")
        else:
            emit("status", "DeepDanbooru model already installed; skipping download.")

        # 5. Extract model
        emit("step", 4)
        if not model_file.exists():
            MODEL_DIR.parent.mkdir(parents=True, exist_ok=True)
            with zipfile.ZipFile(ROOT / MODEL_ZIP_NAME) as zf:
                zf.extractall(MODEL_DIR)
            (ROOT / MODEL_ZIP_NAME).unlink(missing_ok=True)
            # Handle archives that contain a top-level directory.
            nested = MODEL_DIR / MODEL_FOLDER
            if not model_file.exists() and (nested / "project.json").exists():
                for child in nested.iterdir():
                    target = MODEL_DIR / child.name
                    if target.exists():
                        if target.is_dir():
                            shutil.rmtree(target)
                        else:
                            target.unlink()
                    child.rename(target)
                nested.rmdir()
        if not model_file.exists():
            raise RuntimeError(
                "The model archive was extracted, but project.json was not found. "
                "The archive layout may have changed."
            )

        # Check the exact files required by the tagger.
        required = ("model-resnet_custom_v3.h5", "tags.txt")
        missing = [name for name in required if not (MODEL_DIR / name).is_file()]
        if missing:
            raise RuntimeError("Model is missing required file(s): " + ", ".join(missing))

        # 6. Launch the app
        emit("step", 5)
        emit("status", "Launching ImageTagger…")
        emit("launch")
    except Exception as exc:
        emit("error", str(exc))

class SetupWindow:
    def __init__(self, root):
        self.root = root
        root.title("ImageTagger Setup")
        root.geometry("620x430")
        root.minsize(560, 390)
        root.configure(bg="#111827")
        self.current_step = -1
        self.rows = []
        self.build()
        self.poll()
        threading.Thread(target=install, daemon=True).start()

    def build(self):
        outer = tk.Frame(self.root, bg="#111827", padx=26, pady=22)
        outer.pack(fill="both", expand=True)
        tk.Label(
            outer, text="IMAGE TAGGER", fg="#f8fafc", bg="#111827",
            font=("Segoe UI", 20, "bold")
        ).pack(anchor="w")
        tk.Label(
            outer, text="Preparing the app automatically — no setup choices required.",
            fg="#9ca3af", bg="#111827", font=("Segoe UI", 10)
        ).pack(anchor="w", pady=(4, 18))

        self.overall = ttk.Progressbar(outer, mode="determinate", maximum=len(STEPS))
        self.overall.pack(fill="x", pady=(0, 18))
        self.status = tk.Label(
            outer, text="Starting setup…", fg="#d1d5db", bg="#111827",
            font=("Segoe UI", 10), anchor="w"
        )
        self.status.pack(fill="x", pady=(0, 12))

        self.list_frame = tk.Frame(outer, bg="#1f2937", padx=14, pady=12)
        self.list_frame.pack(fill="both", expand=True)
        for i, step in enumerate(STEPS):
            line = tk.Frame(self.list_frame, bg="#1f2937")
            line.pack(fill="x", pady=6)
            marker = tk.Label(line, text="○", fg="#6b7280", bg="#1f2937", width=3, font=("Segoe UI", 12))
            marker.pack(side="left")
            name = tk.Label(line, text=step, fg="#cbd5e1", bg="#1f2937", font=("Segoe UI", 10))
            name.pack(side="left")
            self.rows.append((marker, name))

        self.detail = tk.Label(
            outer, text="Downloads and installation progress will appear here.",
            fg="#94a3b8", bg="#111827", font=("Segoe UI", 9), anchor="w"
        )
        self.detail.pack(fill="x", pady=(14, 0))

    def set_step(self, index):
        self.current_step = index
        self.overall["value"] = index
        for i, (marker, name) in enumerate(self.rows):
            if i < index:
                marker.config(text="✓", fg="#34d399")
            elif i == index:
                marker.config(text="●", fg="#60a5fa")
            else:
                marker.config(text="○", fg="#6b7280")
        if 0 <= index < len(STEPS):
            self.status.config(text=STEPS[index] + "…")

    def poll(self):
        try:
            while True:
                event = EVENTS.get_nowait()
                kind, *values = event
                if kind == "step":
                    self.set_step(values[0])
                elif kind == "status":
                    self.detail.config(text=values[0])
                elif kind == "progress":
                    fraction, text = values
                    self.detail.config(text=text)
                    self.root.update_idletasks()
                elif kind == "launch":
                    self.overall["value"] = len(STEPS)
                    for marker, _ in self.rows:
                        marker.config(text="✓", fg="#34d399")
                    self.status.config(text="Setup complete. Starting ImageTagger…")
                    self.detail.config(text="The setup window will close when ImageTagger starts.")
                    subprocess.Popen([str(PYTHON_EXE), str(APP_FILE)], cwd=str(ROOT))
                    self.root.after(900, self.root.destroy)
                    return
                elif kind == "error":
                    self.status.config(text="Setup could not finish.")
                    messagebox.showerror("ImageTagger setup error", values[0])
                    self.root.destroy()
                    return
        except queue.Empty:
            pass
        self.root.after(100, self.poll)

def main():
    root = tk.Tk()
    try:
        ttk.Style().theme_use("clam")
    except tk.TclError:
        pass
    SetupWindow(root)
    root.mainloop()

if __name__ == "__main__":
    main()
